"""Build a plain Frida 16 script; no npm or bridge required at runtime."""
from pathlib import Path
import argparse

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('--embedded', action='store_true', help='Build the embedded DG-LAB V4 server variant')
args = parser.parse_args()

ROOT = Path(__file__).resolve().parent
parts = [
    "// Generated by hooks/judgment/build.py. Edit src/, then rebuild.\n",
    "globalThis.PHIGROS_WS_OPTIONS = {autoSend:false, autoConnect:false, verbose:false};\n",
    "(function () {\n" + (ROOT / '../../network/ws/phigros_ws.js').read_text(encoding='utf-8') + "\n})();\n",
    (ROOT / 'vendor/qrcode.js').read_text(encoding='utf-8'),
    (ROOT / 'vendor/qrcode_UTF8.js').read_text(encoding='utf-8'),
]
if args.embedded:
    parts = parts[:1] + parts[3:]  # no WS client in the server variant
parts.append((ROOT / 'src/runtime.js').read_text(encoding='utf-8'))
if args.embedded:
    parts.extend((ROOT / '../../network/dglab' / name).read_text(encoding='utf-8')
                 for name in ['core.js', 'vendor/waveforms.js', 'frida.js'])
parts.extend((ROOT / 'src' / name).read_text(encoding='utf-8') for name in ['judgment.js', 'settings.js'])
output = ROOT / ('phigros_dglab.js' if args.embedded else 'phigros_judgment.js')
output.write_text('\n'.join(parts), encoding='utf-8')
print(output)
